import policyFile from "../../../data/treg/data_policy.json";

/**
 * The DATA CATEGORY of every TREG endpoint, read from data/treg/data_policy.json (generated by scripts/treg/build-data-policy.mjs from id, capability, name and summary).
 * Enforced by code: the model never decides who may reach a category, and a category is never shown to a customer.
 *
 *   public       available to every customer
 *   b2b_contact  work email, business phone, professional profile: available to every customer, priced by code from real cost
 *   sensitive    personal contact, reverse lookups, advertising ids, personality: the admin and accounts the admin marked «verified business» only
 *   blocked      write actions, own-account endpoints, private-messaging deep links, apollo and datagma: never offered, sampled or executed
 *
 * An id the policy does not know is «unclassified»: the sellable catalog never lists one (every sellable id is classified), and the gateway's block list refuses an
 * unknown id of a known provider, so nothing unknown is planned.
 */
export type DataCategory = "public" | "b2b_contact" | "sensitive" | "blocked";
export type PolicyCategoryOrUnknown = DataCategory | "unclassified";

interface PolicyFile {
  version: number;
  pausedProviders: string[];
  counts: Record<DataCategory, number>;
  rule: Record<string, string>;
  endpoints: Record<string, DataCategory>;
}

const policy = policyFile as unknown as PolicyFile;

export const DATA_POLICY_COUNTS: Readonly<Record<DataCategory, number>> = policy.counts;

const PAUSED: ReadonlySet<string> = new Set(policy.pausedProviders.map((p) => p.toLowerCase()));

export function categoryOf(endpointId: string): PolicyCategoryOrUnknown {
  const id = String(endpointId ?? "").trim();
  if (Object.prototype.hasOwnProperty.call(policy.endpoints, id)) return policy.endpoints[id];
  // the endpoints of a paused provider (apollo, datagma) are not in the snapshot: they are blocked by the provider's NAME
  const dot = id.indexOf(".");
  return dot > 0 && PAUSED.has(id.slice(0, dot).toLowerCase()) ? "blocked" : "unclassified";
}

/** The id of the rule that put a non-public endpoint in its category (internal: never shown). */
export function policyRuleOf(endpointId: string): string | null {
  const id = String(endpointId ?? "").trim();
  return Object.prototype.hasOwnProperty.call(policy.rule, id) ? policy.rule[id] : null;
}

export function endpointIdsOf(category: DataCategory): string[] {
  return Object.keys(policy.endpoints).filter((id) => policy.endpoints[id] === category);
}

/** What the caller's account may reach. The admin comes from the session's role; «verified business» is the flag the admin sets on a customer account. */
export interface AccountAccess {
  isAdmin: boolean;
  verifiedBusiness: boolean;
}

export const NO_SENSITIVE_ACCESS: AccountAccess = { isAdmin: false, verifiedBusiness: false };

export function mayUseSensitive(access: AccountAccess | null | undefined): boolean {
  return Boolean(access && (access.isAdmin === true || access.verifiedBusiness === true));
}

export type PolicyRefusal = "blocked" | "sensitive_not_allowed";
export type PolicyVerdict = { allowed: true; category: PolicyCategoryOrUnknown } | { allowed: false; category: PolicyCategoryOrUnknown; reason: PolicyRefusal };

/** May this account be offered, sampled or sold this endpoint? Blocked never; sensitive only for an allowed account; everything else yes. */
export function policyVerdict(endpointId: string, access: AccountAccess | null | undefined): PolicyVerdict {
  const category = categoryOf(endpointId);
  if (category === "blocked") return { allowed: false, category, reason: "blocked" };
  if (category === "sensitive" && !mayUseSensitive(access)) return { allowed: false, category, reason: "sensitive_not_allowed" };
  return { allowed: true, category };
}

/** The one sentence a customer who may not use a sensitive service reads (no provider, no endpoint, no category name). Nothing is held. */
export const SENSITIVE_NOT_VERIFIED_AR = "هذه الخدمة متاحة لحسابات الأعمال الموثّقة فقط؛ تواصل مع الدعم لتوثيق حسابك، ولم يُحجز أي رصيد.";
